// This file is generated by AI.

// 项目会话 (上次打开的场景选项卡) 的断言。

import { describe, expect, it } from 'vitest';

import {
  collectSceneTabs,
  normalizeSession,
  SESSION_TAB_LIMIT,
  sessionFromTabs,
  type ProjectSession,
} from '../src/lib/session';

const tab = (id: string, kind: string, path: string) => ({ id, kind, path });

describe('collectSceneTabs', () => {
  it('只取场景卡, 按顺序去重', () => {
    const tabs = [
      tab('scene:C:\\p\\game\\scene\\a.txt', 'scene', 'C:\\p\\game\\scene\\a.txt'),
      tab('resource:C:\\p\\game\\config.txt', 'resource', 'C:\\p\\game\\config.txt'),
      tab('scene:C:\\p\\game\\scene\\b.txt', 'scene', 'C:\\p\\game\\scene\\b.txt'),
      tab('scene:C:\\P\\game\\scene\\A.txt', 'scene', 'C:\\P\\game\\scene\\A.txt'),
    ];
    expect(collectSceneTabs(tabs)).toEqual(['C:\\p\\game\\scene\\a.txt', 'C:\\p\\game\\scene\\b.txt']);
  });

  it('超过上限时截断', () => {
    const tabs = Array.from({ length: SESSION_TAB_LIMIT + 5 }, (_, index) =>
      tab(`scene:${index}`, 'scene', `C:\\p\\game\\scene\\${index}.txt`)
    );
    expect(collectSceneTabs(tabs)).toHaveLength(SESSION_TAB_LIMIT);
  });

  it('没有场景卡时返回空', () => {
    expect(collectSceneTabs([tab('guidance', 'guidance', '')])).toEqual([]);
  });
});

describe('sessionFromTabs', () => {
  it('记下激活的场景卡', () => {
    const tabs = [tab('scene:a', 'scene', 'C:\\p\\a.txt'), tab('scene:b', 'scene', 'C:\\p\\b.txt')];
    const session = sessionFromTabs(tabs, 'scene:b');
    expect(session.tabs).toEqual(['C:\\p\\a.txt', 'C:\\p\\b.txt']);
    expect(session.activeTab).toBe('C:\\p\\b.txt');
  });

  it('激活的不是场景卡时不记激活项', () => {
    const tabs = [tab('scene:a', 'scene', 'C:\\p\\a.txt'), tab('workbench', 'voice-workbench', '')];
    expect(sessionFromTabs(tabs, 'workbench').activeTab).toBeNull();
  });
});

describe('normalizeSession', () => {
  it('丢弃损坏的条目并补默认值', () => {
    const session = normalizeSession({ tabs: ['C:\\a.txt', 42, '', 'c:\\A.txt'], activeTab: '  ' });
    expect(session).toEqual({ tabs: ['C:\\a.txt'], activeTab: null, updatedAt: 0 } satisfies ProjectSession);
  });

  it('结构不对时返回 null', () => {
    expect(normalizeSession(null)).toBeNull();
    expect(normalizeSession({ tabs: 'not-an-array' })).toBeNull();
  });

  it('保留 updatedAt', () => {
    expect(normalizeSession({ tabs: [], updatedAt: 123 })?.updatedAt).toBe(123);
  });
});
